mapper.select:
SELECT m.id AS merchant_id, m.name AS merchant_name, m.category, m.latitude, m.longitude, EXISTS ( SELECT 1 FROM reservations r JOIN reservation_products rp ON rp.id = r.product_id WHERE r.user_id = #{userId} AND r.workation_id = #{workationId} AND r.status IN ('CONFIRMED', 'COMPLETED') AND rp.merchant_id = m.id ) AS reserved FROM merchants m WHERE m.name LIKE CONCAT('%', #{keyword}, '%') AND m.region_id = #{regionId}
AND m.category IN
#{category}
ORDER BY reserved DESC, m.name ASC, m.id ASC LIMIT #{size}
